# Surah Al-Munafiqun (chapter 63) — all ayat 1-11 (IDs 5189-5199)
SURAH = 63

ENTRIES = {
5189: (
"بسم اللہ الرّحْمٰن الرّحِیْم — جب منافق تمہارے پاس آتے ہیں تو کہتے ہیں گواہی دیتے ہیں کہ بے شک تو اللہ کے رسول ہے — اور اللہ جانتا ہے کہ بے شک تو اس کا رسول ہے — اور اللہ گواہی دیتا ہے کہ منافق جھوٹے ہیں",
"""۱۔ منافقوں کا جھوٹ — إذا جاءک المنافقون قالوا نشهد إنک لرسول الله؛ و الله یعلم إنک لرسوله؛ و الله یشهد إن المنافقین لکاذبون۔
۲۔ ’’إِذَا جَاءَكَ الْمُنَافِقُونَ قَالُوا نَشْهَدُ إِنَّكَ لَرَسُولُ اللَّهِ وَاللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُ وَاللَّهُ يَشْهَدُ إِنَّ الْمُنَافِقِينَ لَكَاذِبُونَ‘‘ — جب منافق تمہارے پاس آتے ہیں تو کہتے ہیں گواہی دیتے ہیں کہ بے شک تو اللہ کے رسول ہے — اور اللہ جانتا ہے کہ بے شک تو اس کا رسول ہے — اور اللہ گواہی دیتا ہے کہ منافق جھوٹے ہیں — یعنی جب منافق تمہارے پاس آتے ہیں تو کہتے ہیں گواہی دیتے ہیں کہ بے شک تو اللہ کے رسول ہے اور اللہ جانتا ہے کہ بے شک تو اس کا رسول ہے اور اللہ گواہی دیتا ہے کہ منافق جھوٹے ہیں۔
۳۔ عملی سبق: نفاق سے بچو؛ اللہ سے ڈرو۔"""
),
5190: (
"انہوں نے اپنی قسموں کو ڈھال بنایا اور اللہ کے راستے سے روکا — بے شک وہ برا کرتے ہیں جو وہ کرتے ہیں",
"""۱۔ جھوٹی قسمیں — اتخذوا أیمانهم جنّۃ فصدّوا عن سبیل الله؛ إنهم ساء ما کانوا یعملون۔
۲۔ ’’اتَّخَذُوا أَيْمَانَهُمْ جُنَّۃً فَصَدُّوا عَن سَبِيلِ اللَّه إِنَّهُمْ سَاءَ مَا كَانُوا يَعْمَلُونَ‘‘ — انہوں نے اپنی قسموں کو ڈھال بنایا اور اللہ کے راستے سے روکا — بے شک وہ برا کرتے ہیں جو وہ کرتے ہیں — یعنی انہوں نے اپنی قسموں کو ڈھال بنایا اور اللہ کے راستے سے روکا بے شک وہ برا کرتے ہیں جو وہ کرتے ہیں۔
۳۔ عملی سبق: جھوٹی قسمیں نہ کھاؤ؛ اللہ سے ڈرو۔"""
),
5191: (
"یہ اس لیے کہ انہوں نے ایمان لایا پھر کفر کیا پس ان کے دلوں پر مہر لگا دی گئی — پس وہ سمجھتے نہیں",
"""۱۔ دلوں پر مہر — ذلک بأنهم آمنوا ثم کفروا فطُبِع علی قلوبهم؛ فهم لا یفقهون۔
۲۔ ’’ذَٰلِكَ بِأَنَّهُمْ آمَنُوا ثُمَّ كَفَرُوا فَطُبِعَ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَفْقَهُونَ‘‘ — یہ اس لیے کہ انہوں نے ایمان لایا پھر کفر کیا پس ان کے دلوں پر مہر لگا دی گئی — پس وہ سمجھتے نہیں — یعنی یہ اس لیے کہ انہوں نے ایمان لایا پھر کفر کیا پس ان کے دلوں پر مہر لگا دی گئی پس وہ سمجھتے نہیں۔
۳۔ عملی سبق: ایمان پر ثابت قدم رہو؛ اللہ سے ڈرو۔"""
),
5192: (
"اور جب تم انہیں دیکھتے ہو ان کے جسم تمہیں بھلے لگتے ہیں — اور اگر وہ بات کریں تو تم ان کی بات سنتے ہو — گویا وہ تکیے دار لکڑھیاں ہیں — وہ ہر چنگھاڑ کو اپنے اوپر سمجھتے ہیں — وہی دشمن ہیں ان سے ڈرو — اللہ انہیں ہلاک کرے — وہ کہاں الٹے جاتے ہیں؟",
"""۱۔ منافقوں کی حقیقت — و إذا رأیتهم تعجبک أجسامهم؛ و إن یقولوا تسمع لقولهم؛ کأنهم خشب مسندۃ؛ یحسبون کل صیحۃ علیهم؛ هم العدو فاحذرهم؛ قاتلهم الله؛ أنی یؤفکون۔
۲۔ ’’وَإِذَا رَأَيْتَهُمْ تُعْجِبُكَ أَجْسَامُهُمْ وَإِن يَقُولُوا تَسْمَعْ لِقَوْلِهِمْ كَأَنَّهُمْ خُشُبٌ مُّسَنَّدَۃٌ يَحْسَبُونَ كُلَّ صَيْحَۃٍ عَلَيْهِمْ هُمُ الْعَدُوُّ فَاحْذَرْهُمْ قَاتَلَهُمُ اللَّهُ أَنَّىٰ يُؤْفَكُونَ‘‘ — اور جب تم انہیں دیکھتے ہو ان کے جسم تمہیں بھلے لگتے ہیں — اور اگر وہ بات کریں تو تم ان کی بات سنتے ہو — گویا وہ تکیے دار لکڑھیاں ہیں — وہ ہر چنگھاڑ کو اپنے اوپر سمجھتے ہیں — وہی دشمن ہیں ان سے ڈرو — اللہ انہیں ہلاک کرے — وہ کہاں الٹے جاتے ہیں؟ — یعنی اور جب تم انہیں دیکھتے ہو ان کے جسم تمہیں بھلے لگتے ہیں اور اگر وہ بات کریں تو تم ان کی بات سنتے ہو گویا وہ تکیے دار لکڑھیاں ہیں وہ ہر چنگھاڑ کو اپنے اوپر سمجھتے ہیں وہی دشمن ہیں ان سے ڈرو اللہ انہیں ہلاک کرے وہ کہاں الٹے جاتے ہیں۔
۳۔ عملی سبق: منافقوں سے ہوشیار رہو؛ اللہ سے ڈرو۔"""
),
5193: (
"اور جب ان سے کہا جائے آؤ تاکہ رسول اللہ تمہارے لیے بخشش مانگیں تو وہ سر ہلاتے ہیں اور تم انہیں دیکھتے ہو کہ وہ تکبر کرتے ہوئے منہ موڑ لیتے ہیں",
"""۱۔ سر ہلاتے ہیں — و إذا قیل لهم تعالوا یستغفر لکم رسول الله لوّوا رءوسهم و رأیتهم یصدّون و هم مستکبرون۔
۲۔ ’’وَإِذَا قِيلَ لَهُمْ تَعَالَوْا يَسْتَغْفِرْ لَكُمْ رَسُولُ اللَّهِ لَوَّوْا رُءُوسَهُمْ وَرَأَيْتَهُمْ يَصُدُّونَ وَهُم مُّسْتَكْبِرُونَ‘‘ —اور جب ان سے کہا جائے آؤ تاکہ رسول اللہ تمہارے لیے بخشش مانگیں تو وہ سر ہلاتے ہیں اور تم انہیں دیکھتے ہو کہ وہ تکبر کرتے ہوئے منہ موڑ لیتے ہیں۔
۳۔ عملی سبق: تکبر نہ کرو؛ اللہ سے ڈرو۔"""
),
5194: (
"برابر ہے ان پر خواہ تو ان کے لیے بخشش مانگے یا تو ان کے لیے نہ مانگے — اللہ انہیں نہیں بخشے گا — بے شک اللہ فاسقوں کی راہ نہیں دکھاتا",
"""۱۔ ناقابلِ بخشش — سواء علیهم أستغفرت لهم أم لم تستغفر لهم لن یغفر الله لهم؛ إن الله لا یهدي القوم الفاسقین۔
۲۔ ’’سَوَاءٌ عَلَيْهِمْ أَسْتَغْفَرْتَ لَهُمْ أَمْ لَمْ تَسْتَغْفِرْ لَهُمْ لَن يَغْفِرَ اللَّهُ لَهُمْ إِنَّ اللَّهَ لَا يَهْدِي الْقَوْمَ الْفَاسِقِينَ‘‘ — برابر ہے ان پر خواہ تو ان کے لیے بخشش مانگے یا تو ان کے لیے نہ مانگے — اللہ انہیں نہیں بخشے گا — بے شک اللہ فاسقوں کی راہ نہیں دکھاتا — یعنی برابر ہے ان پر خواہ تو ان کے لیے بخشش مانگے یا تو ان کے لیے نہ مانگے اللہ انہیں نہیں بخشے گا بے شک اللہ فاسقوں کی راہ نہیں دکھاتا۔
۳۔ عملی سبق: نفاق چھوڑو؛ اللہ سے ڈرو۔"""
),
5195: (
"وہی ہیں جو کہتے ہیں رسول اللہ کے پاس جو ہیں ان پر خرچ نہ کرو یہاں تک کہ وہ بکھر جائیں — اور آسمانوں اور زمین کے خزانے اللہ کے ہیں لیکن منافق نہیں سمجھتے",
"""۱۔ منافقوں کا بخل — هم الذین یقولون لا تنفقوا علی من عند رسول الله حتی ینفضّوا؛ و لله خزائن السماوات و الأرض و لکن المنافقین لا یفقهون۔
۲۔ ’’هُمُ الَّذِينَ يَقُولُونَ لَا تُنفِقُوا عَلَىٰ مَنْ عِندَ رَسُولِ اللَّهِ حَتَّىٰ يَنفَضُّوا وَلِلَّهِ خَزَائِنُ السَّمَاوَاتِ وَالْأَرْضِ وَلَٰكِنَّ الْمُنَافِقِينَ لَا يَفْقَهُونَ‘‘ — وہی ہیں جو کہتے ہیں رسول اللہ کے پاس جو ہیں ان پر خرچ نہ کرو یہاں تک کہ وہ بکھر جائیں — اور آسمانوں اور زمین کے خزانے اللہ کے ہیں لیکن منافق نہیں سمجھتے — یعنی وہی ہیں جو کہتے ہیں رسول اللہ کے پاس جو ہیں ان پر خرچ نہ کرو یہاں تک کہ وہ بکھر جائیں اور آسمانوں اور زمین کے خزانے اللہ کے ہیں لیکن منافق نہیں سمجھتے۔
۳۔ عملی سبق: اللہ کی راہ میں خرچ کرو؛ اللہ سے ڈرو۔"""
),
5196: (
"وہ کہتے ہیں اگر ہم مدینہ واپس جائیں تو عزت والا ذلت والے کو وہاں سے نکال دے گا — اور عزت اللہ کی ہے اور اس کے رسول کی اور مؤمنوں کی لیکن منافق نہیں جانتے",
"""۱۔ عزت کس کی ہے — یقولون لئن رجعنا إلی المدینۃ لیخرجنّ الأعز منها الأذل؛ و لله العزۃ و لرسوله و للمؤمنین و لکن المنافقین لا یعلمون۔
۲۔ ’’يَقُولُونَ لَئِن رَّجَعْنَا إِلَى الْمَدِينَۃِ لَيُخْرِجَنَّ الْأَعَزُّ مِنْهَا الْأَذَلَّ وَلِلَّهِ الْعِزَّۃُ وَلِرَسُولِهِ وَلِلْمُؤْمِنِينَ وَلَٰكِنَّ الْمُنَافِقِينَ لَا يَعْلَمُونَ‘‘ — وہ کہتے ہیں اگر ہم مدینہ واپس جائیں تو عزت والا ذلت والے کو وہاں سے نکال دے گا — اور عزت اللہ کی ہے اور اس کے رسول کی اور مؤمنوں کی لیکن منافق نہیں جانتے — یعنی وہ کہتے ہیں اگر ہم مدینہ واپس جائیں تو عزت والا ذلت والے کو وہاں سے نکال دے گا اور عزت اللہ کی ہے اور اس کے رسول کی اور مؤمنوں کی لیکن منافق نہیں جانتے۔
۳۔ عملی سبق: عزت اللہ کی اطاعت میں ہے؛ اللہ سے ڈرو۔"""
),
5197: (
"اے ایمان والو تمہارا مال اور تمہاری اولاد تمہیں اللہ کے ذکر سے غافل نہ کرے — اور جو ایسا کرے وہی خسارے میں ہے",
"""۱۔ مال و اولاد کا فتنہ — یا أیها الذین آمنوا لا تلهکم أموالکم و لا أولادکم عن ذکر الله؛ و من یفعل ذلک فأولئک هم الخاسرون۔
۲۔ ’’يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُلْهِكُمْ أَمْوَالُكُمْ وَلَا أَوْلَادُكُمْ عَن ذِكْرِ اللَّهِ وَمَن يَفْعَلْ ذَٰلِكَ فَأُولَٰئِكَ هُمُ الْخَاسِرُونَ‘‘ — اے ایمان والو تمہارا مال اور تمہاری اولاد تمہیں اللہ کے ذکر سے غافل نہ کرے — اور جو ایسا کرے وہی خسارے میں ہے — یعنی اے ایمان والو تمہارا مال اور تمہاری اولاد تمہیں اللہ کے ذکر سے غافل نہ کرے اور جو ایسا کرے وہی خسارے میں ہے۔
۳۔ عملی سبق: مال و اولاد سے غافل نہ ہو؛ اللہ سے ڈرو۔"""
),
5198: (
"اور ہمارے دیے ہوئے رزق میں سے خرچ کرو اس سے پہلے کہ تم میں سے کسی کو موت آئے پس وہ کہے اے میرے رب تو نے مجھے قریب کی مدت تک کیوں نہ مؤخر کیا تاکہ میں صدقہ دوں اور نیکوکاروں میں شامل ہو جاؤں",
"""۱۔ موت سے پہلے خرچ کرو — و أنفقوا من ما رزقناکم من قبل أن یأتی أحدکم الموت فیقول رب لولا أخّرتني إلی أجل قریب فأصّدق و أکن من الصالحین۔
۲۔ ’’وَأَنفِقُوا مِن مَّا رَزَقْنَاكُم مِّن قَبْلِ أَن يَأْتِيَ أَحَدَكُمُ الْمَوْتُ فَيَقُولَ رَبِّ لَوْلَا أَخَّرْتَنِي إِلَىٰ أَجَلٍ قَرِيبٍ فَأَصَّدَّقَ وَأَكُن مِّنَ الصَّالِحِينَ‘‘ —اور ہمارے دیے ہوئے رزق میں سے خرچ کرو اس سے پہلے کہ تم میں سے کسی کو موت آئے پس وہ کہے اے میرے رب تو نے مجھے قریب کی مدت تک کیوں نہ مؤخر کیا تاکہ میں صدقہ دوں اور نیکوکاروں میں شامل ہو جاؤں۔
۳۔ عملی سبق: موت سے پہلے خرچ کرو؛ اللہ سے ڈرو۔"""
),
5199: (
"اور اللہ کبھی کسی جان کو مؤخر نہیں کرتا جب اس کی مدت آ جائے — اور اللہ جو تم کرتے ہو اس سے باخبر ہے",
"""۱۔ موت کی مدت — و لن یؤخّر الله نفسًا إذا جاء أجلها؛ و الله خبیر بما تعملون۔
۲۔ ’’وَلَن يُؤَخِّرَ اللَّهُ نَفْسًا إِذَا جَاءَ أَجَلُهَا وَاللَّهُ خَبِيرٌ بِمَا تَعْمَلُونَ‘‘ — اور اللہ کبھی کسی جان کو مؤخر نہیں کرتا جب اس کی مدت آ جائے — اور اللہ جو تم کرتے ہو اس سے باخبر ہے — یعنی اور اللہ کبھی کسی جان کو مؤخر نہیں کرتا جب اس کی مدت آ جائے اور اللہ جو تم کرتے ہو اس سے باخبر ہے۔
۳۔ عملی سبق: موت سے پہلے تیاری کرو؛ اللہ سے ڈرو۔"""
),
}
